// Experimental implementation of foundry_content_search/list/detail.
// Read-only. It intentionally consumes a versioned local spell eligibility index
// because the installed dnd5e Item documents do not store class membership.
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
const root=path.resolve(new URL("../../",import.meta.url).pathname.replace(/^\/+([A-Za-z]):/,"$1:").replaceAll("/","\\"));
const rulesDir=path.join(root,"skills","prep","arcane-dnd5e-rules","references","spellcasting","spells");
const spellRules={};
for(const file of fs.readdirSync(rulesDir).filter(x=>x.endsWith(".md"))){const text=fs.readFileSync(path.join(rulesDir,file),"utf8");const header=text.split(/^#\s+/m)[0];const name=header.match(/^name:\s*(.+)$/m)?.[1]?.trim();const level=Number(header.match(/^level:\s*(\d+)$/m)?.[1]);const cm=header.match(/^classes:\s*([^\n]*(?:\n\s+[a-z]+)*)/im);const classes=cm?cm[1].split(/\s+/).map(x=>x.trim()).filter(Boolean):[];if(name&&Number.isFinite(level)&&classes.length)spellRules[name.toLowerCase()]={name,level,classes};}
const origin="http://127.0.0.1:30101",port=9231,worldId="cos-a";
const pages=(await (await fetch(`http://127.0.0.1:${port}/json/list`)).json()).filter(p=>p.type==="page"&&p.url===`${origin}/game`);assert.equal(pages.length,1);
const ws=new WebSocket(pages[0].webSocketDebuggerUrl);await new Promise((r,j)=>{ws.addEventListener("open",r,{once:true});ws.addEventListener("error",j,{once:true});});let seq=0;const pending=new Map();ws.addEventListener("message",e=>{const m=JSON.parse(e.data),p=pending.get(m.id);if(!p)return;pending.delete(m.id);clearTimeout(p.timer);if(m.error||m.result?.exceptionDetails)p.reject(Error(JSON.stringify(m.error??m.result.exceptionDetails)));else p.resolve(m.result?.result?.value);});
const evalPage=(code,input)=>new Promise((resolve,reject)=>{const id=++seq,timer=setTimeout(()=>{pending.delete(id);reject(Error("CDP timeout"));},60000);pending.set(id,{resolve,reject,timer});const expression=`(async()=>{if(location.origin!==${JSON.stringify(origin)}||game.world.id!==${JSON.stringify(worldId)}||!game.ready||!game.user.isGM)throw Error("COS guard");const args=${JSON.stringify(input)};const rules=${JSON.stringify(spellRules)};return await (${code})(args,rules);})()`;ws.send(JSON.stringify({id,method:"Runtime.evaluate",params:{expression,returnByValue:true,awaitPromise:true}}));});
const catalog=String.raw`async function catalog(a,rules){
 const packs=Array.from(game.packs), norm=x=>String(x||'').toLowerCase().trim(), pages=a.page||1,size=Math.min(a.pageSize||20,100);
 const entries=(re,types)=>packs.filter(p=>re.test(p.collection)&&(!types||types.includes(p.documentName))).flatMap(p=>p.index.contents.map(e=>({...e,pack:p.collection,uuid:"Compendium."+p.collection+"."+p.documentName+"."+e._id})));
 if(a.mode==='search'){const aliases={"长棍":"quarterstaff","轻锤":"light hammer"};const q=norm(aliases[a.query]||a.query);const es=entries(a.scope==='world'?/^world\\./:/./,a.type==='actor'?['Actor']:a.type==='scene'?['Scene']:['Item']).filter(e=>norm(e.name).includes(q)||norm(e.system?.identifier).includes(q));return {page:pages,pageSize:size,total:es.length,hasNextPage:pages*size<es.length,items:es.slice((pages-1)*size,pages*size).map(e=>({uuid:e.uuid,name:e.name,type:e.type,packId:e.pack,entryId:e._id,identifier:e.system?.identifier}))};}
 if(a.mode==='detail'){const d=await fromUuid(a.uuid);if(!d)return {error:'NOT_FOUND',uuid:a.uuid};return {uuid:d.uuid,type:d.documentName,name:d.name,source:{scope:d.pack?'compendium':'world',packId:d.pack,entryId:d.id,packageName:d.pack?game.packs.get(d.pack)?.metadata?.packageName:undefined},summary:{level:d.system?.level,identifier:d.system?.identifier,source:d.system?.source},document:d.toObject(),activities:d.type==='spell'||d.type==='weapon'?d.toObject().system?.activities:undefined,effects:d.toObject().effects};}
 if(a.mode!=='list')throw Error('mode must be search/list/detail');
 if(a.type==='spell'){
   const cls=norm(a.class), q=norm(a.query);const es=entries(/^dnd5e\\.spells$|^world\\.arcane-spells-2014$/,['Item']).filter(e=>e.type==='spell').map(e=>{const rule=rules[norm(e.name)];const level=Number(e.system?.level);const eligible=!!rule&&rule.classes.map(norm).includes(cls)&&level<=Number(a.maxLevel??99);return {...e,rule,level,classEligible:eligible,levelEligible:level<=Number(a.maxLevel??99)};}).filter(e=>(!q||norm(e.name).includes(q)||norm(e.system?.identifier).includes(q))&&e.classEligible);return {page:pages,pageSize:size,total:es.length,hasNextPage:pages*size<es.length,items:es.slice((pages-1)*size,pages*size).map(e=>({uuid:e.uuid,name:e.name,type:'spell',level:e.level,classEligible:true,subclassGranted:false,optionalExpansion:false,levelEligible:e.levelEligible,eligibilityReason:'versioned 2014 spell index'}))};
 }
 if(a.type==='monsterAction'){const d=await fromUuid(a.actorUuid);if(!d)return {error:'NOT_FOUND',uuid:a.actorUuid};return {page:1,pageSize:size,total:d.items.filter(i=>['feat','weapon','action'].includes(i.type)).length,hasNextPage:false,items:d.items.filter(i=>['feat','weapon','action'].includes(i.type)).map(i=>({uuid:i.uuid,name:i.name,type:i.type,identifier:i.system?.identifier}))};}
  const re=a.type==='classFeature'?/classes|subclasses|classfeatures/:a.type==='weapon'?/weapon|items|basic/:/./;let es=entries(re,['Item']);if(a.query)es=es.filter(e=>norm(e.name).includes(norm(a.query))||norm(e.system?.identifier).includes(norm(a.query)));return {page:pages,pageSize:size,total:es.length,hasNextPage:pages*size<es.length,items:es.slice((pages-1)*size,pages*size).map(e=>({uuid:e.uuid,name:e.name,type:e.type,identifier:e.system?.identifier,source:e.pack}))};
}`;
try { new Function(`return (${catalog})`); } catch (error) { console.error(catalog.slice(0,600)); throw error; }
const cases=[
 {id:'A1',ops:[['list', {mode:'list',scope:'compendium',type:'classFeature',class:'wizard',subclass:'school-of-evocation',characterLevel:5,pageSize:50}],['spells',{mode:'list',scope:'compendium',type:'spell',class:'wizard',maxLevel:3,pageSize:100}],['fireball',{mode:'list',scope:'compendium',type:'spell',class:'wizard',maxLevel:3,query:'fireball'}],['staff',{mode:'search',scope:'compendium',type:'item',query:'长棍'}]]},
 {id:'A3',ops:[['class',{mode:'list',scope:'compendium',type:'classFeature',class:'cleric',subclass:'life-domain',characterLevel:3}],['spells',{mode:'list',scope:'compendium',type:'spell',class:'cleric',maxLevel:2}],['hammer',{mode:'search',scope:'compendium',type:'item',query:'轻锤'}]]},
 {id:'B1',actor:'Compendium.dnd5e.monsters.Actor.7tRhrxuknTpHpYcA',class:'fighter',sub:'champion'},
 {id:'B2',actor:'Compendium.dnd5e.monsters.Actor.TjWQOgI3A4UAl7lC',class:'rogue',sub:'thief'},
 {id:'B3',actor:'Compendium.dnd5e.monsters.Actor.HB49mCOVBXwWeKWQ',class:'wizard',sub:'school-of-evocation'}
];
for(const c of cases){if(c.actor)c.ops=[['actor',{mode:'detail',scope:'compendium',uuid:c.actor}],['class',{mode:'list',scope:'compendium',type:'classFeature',class:c.class,subclass:c.sub,characterLevel:c.id==='B2'?3:5}],...(c.id==='B3'?[['fireball',{mode:'list',scope:'compendium',type:'spell',class:'wizard',maxLevel:3,query:'fireball'}]]:[])];const out={id:c.id,steps:[],ok:true};for(const [name,input] of c.ops){const value=await evalPage(catalog,input);out.steps.push({name,input,total:value.total,items:value.items?.slice(0,3),error:value.error});if(name==='fireball'&&!value.items?.some(i=>i.name.toLowerCase()==='fireball'))out.ok=false;if(name==='spells'&&!value.items?.length)out.ok=false;if(name==='actor'&&value.type!=='Actor')out.ok=false;}console.log(JSON.stringify(out));}
ws.close();
